class Viewer:
    def __init__(self, root, twin, model, capture_dir):
        import tkinter as tk
        from tkinter.font import Font

        self.root, self.twin, self.capture_dir = root, twin, capture_dir
        self.model_id = hashlib.sha256(
            (model / "integer_model.npz").read_bytes()
        ).hexdigest()
        self.live_fps = None
        self.galleries = {}
